from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Anorak":"Hooded outer jacket, often wind/water resistant; exact insulation and waterproofing depend on fabric/construction.","Belt":"Strap fastens around waist to hold clothing or accessories; fit should be comfortable, not tight.","Coat":"Outer garment provides warmth/weather protection; material and length vary.","Denim Jacket":"Jacket made mainly from denim; durable woven cotton construction gives structure but not waterproofing by itself.","Earmuffs":"Pads cover outer ears for warmth or hearing protection depending design; winter earmuffs do not replace certified hearing protectors.","Flip-flops":"Open sandals held by toe/foot straps; easy airflow but little toe/heel protection or traction for rough activity.","Gown":"Long garment; can mean formal dress, nightwear, medical gown, or robe depending context.","Hat":"Head covering provides shade, warmth, protection, or style depending type.","Indoor Shoes":"Footwear reserved for indoor surfaces; keeps outdoor dirt separate and often emphasizes light comfort.","Jeans":"Denim trousers with sturdy woven fabric and seams; fit should allow normal movement.","Knit Cap":"Soft knitted close-fitting hat retains warmth around head; fiber and thickness affect insulation.","Leggings":"Stretch close-fitting trousers; flexible for movement but warmth/weather protection depends fabric.","Moccasins":"Soft footwear inspired by Indigenous North American moccasin traditions; modern products vary, so avoid treating one commercial style as universal.","Necktie":"Long fabric accessory knotted at neck; should not be worn where loose neckwear could catch in machinery/play equipment.","Overcoat":"Long outer coat worn over other clothes for cold-weather insulation.","Pajamas":"Sleepwear designed for comfort; fabric, fit, and fire-safety standards vary by market/age.","Quarter Socks":"Short socks rising above ankle but below crew height; naming varies by brand/region.","Raincoat":"Outer layer designed to resist rain; waterproof/breathable performance depends material and seams.","Socks":"Foot layers absorb moisture, reduce friction, and add warmth; clean dry fit supports comfort.","T-shirt":"Light knit shirt with short sleeves in common form; works as base/single layer depending weather.","Ugg Boots":"UGG is a brand strongly associated with sheepskin-style boots; mapped boots are warm footwear, not a generic technical category.","Velcro Shoes":"Shoes using hook-and-loop straps for closure; fit still matters even when fastening is easy.","Wool Hat":"Hat made partly/fully from wool; wool fibers can insulate even when slightly damp.","X-shaped Suspenders":"Suspenders whose back straps cross in an X; they support trousers from shoulders rather than tightening waist.","Yoga Pants":"Stretch trousers designed for movement/comfort; not weather-specific by name alone.","Zori Sandals":"Traditional Japanese thong sandals with flat sole and straps; materials/forms vary historically and today.","Apron":"Protective garment covers front of clothing during cooking/craft/work; it is not weather outerwear.","Boots":"Footwear extending above ankle; waterproofing, insulation, safety toe, or fashion role depends design.","Espadrilles":"Light shoes traditionally with rope/jute-style soles and fabric uppers; suited to dry casual conditions more than wet rough terrain.","Fleece":"Soft synthetic or wool-like insulating fabric/garment; traps air for warmth but may not block wind/rain alone.","Gloves":"Separate-finger hand coverings provide warmth, grip, protection, or hygiene depending type.","Infinity Scarf":"Looped scarf has no loose ends but can still snag; remove around machinery/climbing hazards.","Jacket":"Hip/waist-length outer garment; insulation/weather resistance varies widely.","Knee Socks":"Socks extend to near knee for warmth, uniform, sport, or style; fit should not restrict circulation.","Lace-up Shoes":"Shoes secured with laces; tied laces prevent trips and maintain fit.","Mittens":"Hand covering groups fingers together for warmth; reduced finger dexterity is the tradeoff.","Overall":"One-piece or bib garment covers torso/legs for work, protection, or style; exact meaning varies.","Poncho":"Loose outer covering with opening for head; rain ponchos shed water but loose fabric needs care near wind/machinery.","Running Shoes":"Athletic shoes designed for running with cushioning/traction/support features that vary by model and runner.","Uniform":"Standardized clothing identifies school/work/team; it does not determine skill or personality.","Vest":"Sleeveless garment adds layer, visibility, or protection depending design; ordinary fashion vest is not PPE.","Xmas Sweater":"Holiday-themed sweater label describes decoration/seasonal style, not fabric or warmth standard.","Cap":"Close-fitting/brimmed headwear depending style; baseball-style cap shades face but not full sun exposure.","Dress":"One-piece garment covering torso and extending below waist; length/material/style vary.","Hoodie":"Sweatshirt/jacket with attached hood; drawstrings can be snag hazards in some contexts.","Nightgown":"Loose sleepwear garment; fit/fabric should suit sleep and fire-safety guidance.","Quilted Jacket":"Jacket stitches insulation between layers; quilting holds filling in place and creates warmth.","Trainers":"UK/common term for athletic sneakers; purpose ranges casual wear to sport-specific models.","Wellies":"Waterproof rubber-style boots protect feet from puddles/mud; traction and fit still matter.","Yellow Jacket":"Jacket whose color is yellow; color does not define insulation, waterproofing, or visibility certification.","Zipper Jacket":"Jacket closes with zipper teeth/slider; fingers/fabric can catch if rushed.","Scarf":"Long neck fabric adds warmth/style; loose ends require care around machinery/play equipment.",}
ACTIONS={"Necktie":"Point; show a loose loop away from neck—no tying around body.","Infinity Scarf":"Point; no wrapping gesture around neck.","Scarf":"Point; trace one loose line, no neck wrapping.","Lace-up Shoes":"Air-tie two short imaginary laces while seated/still.","Flip-flops":"Point; no running mime.","Zori Sandals":"Point; no running mime.","Poncho":"Point; spread hands like a loose layer, no face covering.","Hoodie":"Point; say drawstrings stay away from snag hazards."}
